text:
help:
	@echo "Available targets:"
	@echo "  run        - Bootstrap the full environment (install tools, provision cluster)"
	@echo "  down       - Destroy the cluster and all resources"
	@echo "  push       - Bump patch version, tag, and push to trigger CI"
	@echo "  tools      - Install necessary tools only"
	@echo "  tofu       - Initialize OpenTofu"
	@echo "  apply      - Apply OpenTofu configuration"
	@echo "  fix-egress - Repair nested-Docker egress (Codespaces) and verify nodes"
	@echo "  llama      - Build llama-server from a pinned llama.cpp tag into .local/"
	@echo "  models     - Download the ADR-0001 embedding GGUFs into .local/models (checksummed)"
	@echo "  clean-llama - Remove .local/llama.cpp and .local/models"

.PHONY: help run tools fix-egress tofu apply down push llama models clean-llama

tools:
	@curl -fsSL https://get.opentofu.org/install-opentofu.sh | sh -s -- --install-method standalone
	@curl -sS https://webi.sh/k9s | bash
	@ARCH=$$(uname -m | sed 's/x86_64/amd64/;s/aarch64/arm64/'); \
	  OS=$$(uname -s | tr '[:upper:]' '[:lower:]'); \
	  curl -fsSLo /tmp/kind "https://kind.sigs.k8s.io/dl/v0.33.0/kind-$$OS-$$ARCH" && \
	  sudo install -m 0755 /tmp/kind /usr/local/bin/kind && rm -f /tmp/kind

fix-egress:
	@bash scripts/fix-egress.sh
	@bash scripts/fix-egress.sh verify abox

push:
	@git fetch origin --tags --force
	$(eval TAG=$(shell git tag --list 'v*' | sort -V | tail -1 | sed 's/^v//' || echo "0.0.0"))
	$(eval MAJOR=$(shell echo $(TAG) | cut -d. -f1))
	$(eval MINOR=$(shell echo $(TAG) | cut -d. -f2))
	$(eval PATCH=$(shell echo $(TAG) | cut -d. -f3))
	$(eval NEW_TAG=v$(MAJOR).$(MINOR).$(shell echo $$(($(PATCH)+1))))
	@git tag $(NEW_TAG)
	@git push origin main $(NEW_TAG)
	@echo "Tagged and pushed $(NEW_TAG)"

clean-llama:
	@rm -rf $(LLAMA_DIR) $(MODELS_DIR)
	@echo "removed $(LLAMA_DIR) and $(MODELS_DIR)"

# ==========================================
# Construct KinD cluster
# ==========================================
resource "kind_cluster" "this" {
  name           = var.cluster_name
  wait_for_ready = true
  kind_config {
    kind        = "Cluster"
    api_version = "kind.x-k8s.io/v1alpha4"
    node {
      role = "control-plane"
    }
    node {
      role = "worker"
    }
    node {
      role = "worker"
    }
    networking {
      kube_proxy_mode = "ipvs"
    }
  }
}

# ==========================================
# Bootstrap Flux Operator + FluxInstance
# ==========================================
# The bootstrap module runs a Job in the cluster that installs the
# flux-operator Helm chart, applies the FluxInstance with create-if-missing
# semantics and waits for it to become Ready. Resources adopted by Flux are
# left alone on subsequent applies, so Terraform never fights reconciliation.
module "flux_operator" {
  source  = "controlplaneio-fluxcd/flux-operator-bootstrap/kubernetes"
  version = "0.8.0"

  depends_on = [kind_cluster.this]

  revision = var.bootstrap_revision

  gitops_resources = {
    instance_yaml = file("${path.module}/flux-instance.yaml")
    operator_chart = {
      version = var.flux_operator_version
    }
  }
}

terraform {
  # >= 1.11 for write-only attributes, required by the
  # flux-operator-bootstrap module (OpenTofu >= 1.11.0).
  required_version = ">= 1.11.0"

  required_providers {
    kind = {
      source  = "tehcyx/kind"
      version = ">= 0.8"
    }
    helm = {
      source  = "hashicorp/helm"
      version = ">= 3.0"
    }
    kubernetes = {
      source  = "hashicorp/kubernetes"
      version = ">= 3.0"
    }
    kubectl = {
      source  = "gavinbunney/kubectl"
      version = ">= 1.14"
    }
  }
}

provider "helm" {
  kubernetes = {
    host                   = kind_cluster.this.endpoint
    client_certificate     = kind_cluster.this.client_certificate
    client_key             = kind_cluster.this.client_key
    cluster_ca_certificate = kind_cluster.this.cluster_ca_certificate
  }
}

provider "kubernetes" {
  host                   = kind_cluster.this.endpoint
  client_certificate     = kind_cluster.this.client_certificate
  client_key             = kind_cluster.this.client_key
  cluster_ca_certificate = kind_cluster.this.cluster_ca_certificate
}

variable "cluster_name" {
  description = "Cluster Name"
  type        = string
  default     = "abox"
}

variable "oci_registry" {
  description = "OCI registry base URL"
  type        = string
  default     = "oci://ghcr.io/vanelin/abox"
}

variable "releases_version" {
  description = "Default tag for releases OCI artifact bootstrap"
  type        = string
  default     = "0.6.5"
}

variable "flux_operator_version" {
  description = "flux-operator Helm chart version. Unset in the module defaults, which floats to latest."
  type        = string
  default     = "0.59.0"
}

variable "bootstrap_revision" {
  description = "Bump to force the flux-operator bootstrap Job to re-run without an input change"
  type        = number
  default     = 1
}
